    private static readonly Dictionary<(Player, PieceType), ImageSource> _imageCache = [];

    public static ImageSource GetImage(Player color, PieceType type)
    {
        if (_imageCache.TryGetValue((color, type), out var cachedImage)) {
            return cachedImage;
        }

        string svgString = GetColoredSvg(color, _svgTemplates[type]);
        ImageSource image = SvgToImageSource(svgString);

        _imageCache[(color, type)] = image;

        return image;
    }

    public static ImageSource GetImage(Piece piece)
    {
        return piece == null ? null : GetImage(piece.Color, piece.Type);
    }

    private static string GetColoredSvg(Player color, string svgTemplate)
    {
        return svgTemplate
            .Replace("{MainColor}", ColorPalette.GetMainColor(color))
            .Replace("{RimColor}", ColorPalette.GetRimColor(color));
    }

    private static ImageSource SvgToImageSource(string svgString)
    {
        string tempFilePath = Path.GetTempFileName() + ".svg";
        File.WriteAllText(tempFilePath, svgString);

        WpfDrawingSettings settings = new() { IncludeRuntime = true };
        FileSvgReader converter = new(settings);
        DrawingGroup drawing = converter.Read(tempFilePath);

        File.Delete(tempFilePath);

        return new DrawingImage(drawing);
    }
}
